export enum AppMode {
  DAILY = 'daily',
  MEETING = 'meeting',
  PRESENTATION = 'presentation',
  DEBATE = 'debate',
  PRONUNCIATION = 'pronunciation',
  CONFIDENCE = 'confidence'
}

export interface TranscriptionEntry {
  id: string;
  role: 'user' | 'model';
  text: string;
  timestamp: number;
}

export interface SessionState {
  isActive: boolean;
  mode: AppMode;
  startTime: number | null;
}

export interface Correction {
  original: string;
  corrected: string;
  explanation: string;
  alternative: string;
}

declare global {
  interface Window {
    aistudio: {
      hasSelectedApiKey: () => Promise<boolean>;
      openSelectKey: () => Promise<void>;
    };
  }
}

export function encode(bytes: Uint8Array): string {
  let binary = '';
  const len = bytes.byteLength;
  for (let i = 0; i < len; i++) {
    binary += String.fromCharCode(bytes[i]);
  }
  return btoa(binary);
}

export function decode(base64: string): Uint8Array {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

export async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number,
  numChannels: number,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

export function createPcmBlob(data: Float32Array): { data: string; mimeType: string } {
  const l = data.length;
  const int16 = new Int16Array(l);
  for (let i = 0; i < l; i++) {
    int16[i] = data[i] * 32768;
  }
  return {
    data: encode(new Uint8Array(int16.buffer)),
    mimeType: 'audio/pcm;rate=16000',
  };
}

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { GoogleGenAI, Modality, LiveServerMessage } from '@google/genai';
import { AppMode, TranscriptionEntry, SessionState } from './types';
import { SYSTEM_INSTRUCTION, MODE_INFO } from './constants';
import { encode, decode, decodeAudioData, createPcmBlob } from './utils/audio';

// UI Components
const SidebarItem: React.FC<{ 
  mode: AppMode; 
  active: boolean; 
  onClick: (mode: AppMode) => void 
}> = ({ mode, active, onClick }) => {
  const info = MODE_INFO[mode];
  return (
    <button
      onClick={() => onClick(mode)}
      className={`w-full flex items-center space-x-3 px-4 py-3 rounded-xl transition-all ${
        active 
          ? 'bg-blue-600 text-white shadow-lg' 
          : 'text-slate-600 hover:bg-slate-100'
      }`}
    >
      <span className="text-xl">{info.icon}</span>
      <span className="font-medium text-sm lg:text-base">{info.title}</span>
    </button>
  );
};

const Header: React.FC<{ needsKey: boolean; onOpenKey: () => void }> = ({ needsKey, onOpenKey }) => (
  <header className="h-16 border-b bg-white flex items-center justify-between px-6 sticky top-0 z-20">
    <div className="flex items-center space-x-2">
      <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center">
        <span className="text-white font-bold">F</span>
      </div>
      <h1 className="text-xl font-bold text-slate-800">FluentDev</h1>
    </div>
    <div className="flex items-center space-x-4">
      {needsKey && (
        <button 
          onClick={onOpenKey}
          className="bg-amber-100 text-amber-700 px-3 py-1.5 rounded-md text-sm font-medium border border-amber-200 hover:bg-amber-200 transition-colors"
        >
          🔑 Set API Key
        </button>
      )}
      <div className="hidden md:flex items-center space-x-1 px-3 py-1 bg-green-50 text-green-700 rounded-full border border-green-100">
        <div className="w-2 h-2 bg-green-500 rounded-full animate-pulse"></div>
        <span className="text-xs font-medium uppercase tracking-wider">Coach Online</span>
      </div>
    </div>
  </header>
);

const App: React.FC = () => {
  const [session, setSession] = useState<SessionState>({
    isActive: false,
    mode: AppMode.DAILY,
    startTime: null
  });
  const [transcriptions, setTranscriptions] = useState<TranscriptionEntry[]>([]);
  const [needsKey, setNeedsKey] = useState(false);
  const [isConnecting, setIsConnecting] = useState(false);

  // Audio Contexts Refs
  const inputAudioCtxRef = useRef<AudioContext | null>(null);
  const outputAudioCtxRef = useRef<AudioContext | null>(null);
  const nextStartTimeRef = useRef<number>(0);
  const activeSourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
  const sessionPromiseRef = useRef<Promise<any> | null>(null);
  const currentTranscriptionRef = useRef({ user: '', model: '' });

  useEffect(() => {
    const checkKey = async () => {
      if (window.aistudio) {
        const hasKey = await window.aistudio.hasSelectedApiKey();
        setNeedsKey(!hasKey);
      }
    };
    checkKey();
  }, []);

  const handleOpenKey = async () => {
    if (window.aistudio) {
      await window.aistudio.openSelectKey();
      setNeedsKey(false);
    }
  };

  const stopSession = useCallback(() => {
    sessionPromiseRef.current?.then((session: any) => session.close());
    sessionPromiseRef.current = null;

    activeSourcesRef.current.forEach(source => source.stop());
    activeSourcesRef.current.clear();

    if (inputAudioCtxRef.current) {
      inputAudioCtxRef.current.close();
      inputAudioCtxRef.current = null;
    }
    if (outputAudioCtxRef.current) {
      outputAudioCtxRef.current.close();
      outputAudioCtxRef.current = null;
    }

    setSession(prev => ({ ...prev, isActive: false }));
    setIsConnecting(false);
  }, []);

  const startSession = useCallback(async (mode: AppMode) => {
    if (session.isActive) stopSession();
    setIsConnecting(true);

    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      const inputCtx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
      const outputCtx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      inputAudioCtxRef.current = inputCtx;
      outputAudioCtxRef.current = outputCtx;
      nextStartTimeRef.current = 0;

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: {
            voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Zephyr' } },
          },
          systemInstruction: SYSTEM_INSTRUCTION + `\n\nCURRENT MODE: ${mode}`,
          inputAudioTranscription: {},
          outputAudioTranscription: {}
        },
        callbacks: {
          onopen: () => {
            setIsConnecting(false);
            setSession({ isActive: true, mode, startTime: Date.now() });

            const source = inputCtx.createMediaStreamSource(stream);
            const scriptProcessor = inputCtx.createScriptProcessor(4096, 1, 1);
            scriptProcessor.onaudioprocess = (e) => {
              const inputData = e.inputBuffer.getChannelData(0);
              const pcmBlob = createPcmBlob(inputData);
              sessionPromise.then((s) => s.sendRealtimeInput({ media: pcmBlob }));
            };
            source.connect(scriptProcessor);
            scriptProcessor.connect(inputCtx.destination);

            // Trigger initial scenario prompt based on mode
            sessionPromise.then(s => s.sendRealtimeInput({ text: `/${mode} scenario start` }));
          },
          onmessage: async (message: LiveServerMessage) => {
            // Audio Handle
            const audioData = message.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
            if (audioData) {
              const audioBuffer = await decodeAudioData(decode(audioData), outputCtx, 24000, 1);
              const source = outputCtx.createBufferSource();
              source.buffer = audioBuffer;
              source.connect(outputCtx.destination);

              nextStartTimeRef.current = Math.max(nextStartTimeRef.current, outputCtx.currentTime);
              source.start(nextStartTimeRef.current);
              nextStartTimeRef.current += audioBuffer.duration;

              activeSourcesRef.current.add(source);
              source.onended = () => activeSourcesRef.current.delete(source);
            }

            // Transcription Handle
            if (message.serverContent?.inputTranscription) {
              currentTranscriptionRef.current.user += message.serverContent.inputTranscription.text;
            }
            if (message.serverContent?.outputTranscription) {
              currentTranscriptionRef.current.model += message.serverContent.outputTranscription.text;
            }

            if (message.serverContent?.turnComplete) {
              const userText = currentTranscriptionRef.current.user;
              const modelText = currentTranscriptionRef.current.model;

              if (userText) {
                setTranscriptions(prev => [...prev, {
                  id: Math.random().toString(),
                  role: 'user',
                  text: userText,
                  timestamp: Date.now()
                }]);
              }
              if (modelText) {
                setTranscriptions(prev => [...prev, {
                  id: Math.random().toString(),
                  role: 'model',
                  text: modelText,
                  timestamp: Date.now()
                }]);
              }

              currentTranscriptionRef.current = { user: '', model: '' };
            }

            if (message.serverContent?.interrupted) {
              activeSourcesRef.current.forEach(s => s.stop());
              activeSourcesRef.current.clear();
              nextStartTimeRef.current = 0;
            }
          },
          onerror: (e) => console.error("Session error:", e),
          onclose: () => stopSession()
        }
      });

      sessionPromiseRef.current = sessionPromise;

    } catch (err) {
      console.error("Failed to start session:", err);
      setIsConnecting(false);
    }
  }, [session.isActive, stopSession]);

  const changeMode = (newMode: AppMode) => {
    if (session.isActive && session.mode === newMode) return;
    setTranscriptions([]);
    startSession(newMode);
  };

  return (
    <div className="flex flex-col min-h-screen bg-slate-50 text-slate-900">
      <Header needsKey={needsKey} onOpenKey={handleOpenKey} />

      <main className="flex-1 flex flex-col md:flex-row max-w-[1600px] mx-auto w-full p-4 md:p-6 gap-6 h-[calc(100vh-64px)] overflow-hidden">

        {/* Navigation Sidebar */}
        <nav className="w-full md:w-64 lg:w-72 flex flex-col space-y-2 overflow-y-auto pr-2">
          <div className="mb-4">
            <h2 className="text-xs font-bold text-slate-400 uppercase tracking-widest px-4 mb-2">Practice Modes</h2>
            <div className="space-y-1">
              {Object.values(AppMode).map((m) => (
                <SidebarItem 
                  key={m} 
                  mode={m} 
                  active={session.mode === m} 
                  onClick={changeMode} 
                />
              ))}
            </div>
          </div>

          <div className="mt-auto bg-blue-50 border border-blue-100 rounded-2xl p-4">
            <h3 className="font-bold text-blue-900 text-sm mb-1">Coach Pro Tip</h3>
            <p className="text-blue-700 text-xs leading-relaxed">
              "Try to use transition words like 'Furthermore' or 'On the other hand' to sound more professional."
            </p>
          </div>
        </nav>

        {/* Chat / Interaction Area */}
        <section className="flex-1 flex flex-col bg-white rounded-3xl border border-slate-200 shadow-sm overflow-hidden">
          <div className="flex-1 overflow-y-auto p-4 md:p-6 space-y-6 scroll-smooth">
            {!session.isActive && !isConnecting && (
              <div className="h-full flex flex-col items-center justify-center text-center max-w-md mx-auto">
                <div className="w-20 h-20 bg-blue-100 rounded-full flex items-center justify-center mb-6">
                  <span className="text-4xl">🎙️</span>
                </div>
                <h2 className="text-2xl font-bold mb-2">Ready to Speak English?</h2>
                <p className="text-slate-500 mb-8">Choose a session mode from the left and start practicing naturally with your AI Coach.</p>
                <button 
                  onClick={() => startSession(session.mode)}
                  className="bg-blue-600 hover:bg-blue-700 text-white px-8 py-3 rounded-2xl font-bold transition-all transform hover:scale-105 shadow-lg"
                >
                  Start Session Now
                </button>
              </div>
            )}

            {isConnecting && (
              <div className="h-full flex flex-col items-center justify-center">
                <div className="relative">
                  <div className="w-16 h-16 border-4 border-blue-200 border-t-blue-600 rounded-full animate-spin"></div>
                  <span className="absolute inset-0 flex items-center justify-center text-xs font-bold text-blue-600">AI</span>
                </div>
                <p className="mt-4 text-slate-500 font-medium">Connecting to your coach...</p>
              </div>
            )}

            {transcriptions.map((t) => (
              <div 
                key={t.id} 
                className={`flex ${t.role === 'user' ? 'justify-end' : 'justify-start'}`}
              >
                <div 
                  className={`max-w-[85%] md:max-w-[70%] p-4 rounded-2xl ${
                    t.role === 'user' 
                      ? 'bg-blue-600 text-white rounded-tr-none' 
                      : 'bg-slate-100 text-slate-800 rounded-tl-none'
                  }`}
                >
                  {t.role === 'model' && (
                    <div className="text-[10px] font-bold uppercase tracking-wider mb-1 opacity-60">Coach</div>
                  )}
                  <p className="text-sm md:text-base leading-relaxed whitespace-pre-wrap">{t.text}</p>
                </div>
              </div>
            ))}
          </div>

          {/* Persistent Control Bar */}
          <div className="p-4 bg-slate-50 border-t flex items-center justify-between">
            <div className="flex items-center space-x-3">
              <div className={`w-3 h-3 rounded-full ${session.isActive ? 'bg-green-500 animate-pulse' : 'bg-slate-300'}`}></div>
              <span className="text-sm font-medium text-slate-600">
                {session.isActive ? `Recording ${MODE_INFO[session.mode].title}...` : 'Microphone Idle'}
              </span>
            </div>

            <div className="flex items-center space-x-4">
               {session.isActive && (
                 <button 
                   onClick={stopSession}
                   className="bg-red-50 text-red-600 hover:bg-red-100 px-4 py-2 rounded-xl font-bold text-sm transition-colors border border-red-100"
                 >
                   End Session
                 </button>
               )}
               <button 
                onClick={() => session.isActive ? stopSession() : startSession(session.mode)}
                className={`w-12 h-12 flex items-center justify-center rounded-full transition-all ${
                  session.isActive 
                    ? 'bg-red-500 hover:bg-red-600 text-white shadow-red-200 shadow-lg scale-110' 
                    : 'bg-blue-600 hover:bg-blue-700 text-white'
                }`}
              >
                {session.isActive ? (
                  <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                  </svg>
                ) : (
                  <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z" />
                  </svg>
                )}
              </button>
            </div>
          </div>
        </section>

        {/* Feedback Panel (Right Side) */}
        <aside className="hidden lg:flex w-80 xl:w-96 flex-col gap-6 overflow-y-auto pr-2">
          <div className="bg-white border border-slate-200 rounded-3xl p-6 shadow-sm">
            <h3 className="text-lg font-bold mb-4 flex items-center gap-2">
              <span className="text-blue-600">📝</span> Live Corrections
            </h3>
            <div className="space-y-4">
              {transcriptions.filter(t => t.role === 'model' && t.text.toLowerCase().includes('mistake:')).length === 0 ? (
                <div className="py-10 text-center">
                  <p className="text-slate-400 text-sm">Corrections will appear here as you speak.</p>
                </div>
              ) : (
                transcriptions.filter(t => t.role === 'model' && t.text.toLowerCase().includes('mistake:')).slice(-3).map((t, idx) => (
                  <div key={idx} className="bg-slate-50 p-4 rounded-xl border border-slate-100">
                    <p className="text-xs text-slate-400 font-mono mb-2">FEEDBACK RECENT</p>
                    <div className="text-sm prose prose-slate max-w-full overflow-hidden text-ellipsis whitespace-pre-wrap">
                      {t.text.split('Mistake:').slice(-1)}
                    </div>
                  </div>
                ))
              )}
            </div>
          </div>

          <div className="bg-gradient-to-br from-slate-800 to-slate-900 rounded-3xl p-6 text-white shadow-xl">
            <h3 className="text-lg font-bold mb-4 flex items-center gap-2">
              <span>📊</span> Session Stats
            </h3>
            <div className="space-y-4">
              <div className="flex justify-between items-center py-2 border-b border-slate-700">
                <span className="text-slate-400 text-sm">Duration</span>
                <span className="font-medium">{session.startTime ? `${Math.floor((Date.now() - session.startTime) / 60000)}m` : '--'}</span>
              </div>
              <div className="flex justify-between items-center py-2 border-b border-slate-700">
                <span className="text-slate-400 text-sm">Vocabulary Points</span>
                <span className="text-blue-400 font-bold">+12</span>
              </div>
              <div className="flex justify-between items-center py-2">
                <span className="text-slate-400 text-sm">Confidence Level</span>
                <div className="flex gap-1">
                  {[1,2,3,4,5].map(i => (
                    <div key={i} className={`w-2 h-4 rounded-sm ${i <= 3 ? 'bg-blue-500' : 'bg-slate-700'}`}></div>
                  ))}
                </div>
              </div>
            </div>
            <button className="w-full mt-6 py-3 bg-white/10 hover:bg-white/20 rounded-xl text-sm font-bold transition-all">
              View Growth Analytics
            </button>
          </div>
        </aside>
      </main>
    </div>
  );
};

export default App;

export enum AppMode {
  DAILY = 'daily',
  MEETING = 'meeting',
  PRESENTATION = 'presentation',
  DEBATE = 'debate',
  PRONUNCIATION = 'pronunciation',
  CONFIDENCE = 'confidence'
}

export interface TranscriptionEntry {
  id: string;
  role: 'user' | 'model';
  text: string;
  timestamp: number;
}

export interface SessionState {
  isActive: boolean;
  mode: AppMode;
  startTime: number | null;
}

export interface Correction {
  original: string;
  corrected: string;
  explanation: string;
  alternative: string;
}

/**
 * Interface for AI Studio environment global
 */
export interface AIStudio {
  hasSelectedApiKey: () => Promise<boolean>;
  openSelectKey: () => Promise<void>;
}

declare global {
  interface Window {
    /**
     * The aistudio object provided by the environment
     */
    readonly aistudio: AIStudio;
  }
}

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { GoogleGenAI, Modality, LiveServerMessage } from '@google/genai';
import { AppMode, TranscriptionEntry, SessionState } from './types';
import { SYSTEM_INSTRUCTION, MODE_INFO } from './constants';
import { encode, decode, decodeAudioData, createPcmBlob } from './utils/audio';

// UI Components
const SidebarItem: React.FC<{ 
  mode: AppMode; 
  active: boolean; 
  onClick: (mode: AppMode) => void 
}> = ({ mode, active, onClick }) => {
  const info = MODE_INFO[mode];
  return (
    <button
      onClick={() => onClick(mode)}
      className={`w-full flex items-center space-x-3 px-4 py-3 rounded-xl transition-all ${
        active 
          ? 'bg-blue-600 text-white shadow-lg' 
          : 'text-slate-600 hover:bg-slate-100'
      }`}
    >
      <span className="text-xl">{info.icon}</span>
      <span className="font-medium text-sm lg:text-base">{info.title}</span>
    </button>
  );
};

const Header: React.FC<{ needsKey: boolean; onOpenKey: () => void }> = ({ needsKey, onOpenKey }) => (
  <header className="h-16 border-b bg-white flex items-center justify-between px-6 sticky top-0 z-20">
    <div className="flex items-center space-x-2">
      <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center">
        <span className="text-white font-bold">F</span>
      </div>
      <h1 className="text-xl font-bold text-slate-800">FluentDev</h1>
    </div>
    <div className="flex items-center space-x-4">
      {needsKey && (
        <button 
          onClick={onOpenKey}
          className="bg-amber-100 text-amber-700 px-3 py-1.5 rounded-md text-sm font-medium border border-amber-200 hover:bg-amber-200 transition-colors"
        >
          🔑 Set API Key
        </button>
      )}
      <div className="hidden md:flex items-center space-x-1 px-3 py-1 bg-green-50 text-green-700 rounded-full border border-green-100">
        <div className="w-2 h-2 bg-green-500 rounded-full animate-pulse"></div>
        <span className="text-xs font-medium uppercase tracking-wider">Coach Online</span>
      </div>
    </div>
  </header>
);

const App: React.FC = () => {
  const [session, setSession] = useState<SessionState>({
    isActive: false,
    mode: AppMode.DAILY,
    startTime: null
  });
  const [transcriptions, setTranscriptions] = useState<TranscriptionEntry[]>([]);
  const [needsKey, setNeedsKey] = useState(false);
  const [isConnecting, setIsConnecting] = useState(false);

  // Audio Contexts Refs
  const inputAudioCtxRef = useRef<AudioContext | null>(null);
  const outputAudioCtxRef = useRef<AudioContext | null>(null);
  const nextStartTimeRef = useRef<number>(0);
  const activeSourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
  const sessionPromiseRef = useRef<Promise<any> | null>(null);
  const currentTranscriptionRef = useRef({ user: '', model: '' });

  useEffect(() => {
    const checkKey = async () => {
      if (window.aistudio) {
        const hasKey = await window.aistudio.hasSelectedApiKey();
        setNeedsKey(!hasKey);
      }
    };
    checkKey();
  }, []);

  const handleOpenKey = async () => {
    if (window.aistudio) {
      await window.aistudio.openSelectKey();
      // MUST assume the key selection was successful to mitigate race condition
      setNeedsKey(false);
    }
  };

  const stopSession = useCallback(() => {
    if (sessionPromiseRef.current) {
      sessionPromiseRef.current.then((s: any) => s.close());
      sessionPromiseRef.current = null;
    }

    activeSourcesRef.current.forEach(source => {
      try { source.stop(); } catch(e) {}
    });
    activeSourcesRef.current.clear();

    if (inputAudioCtxRef.current) {
      inputAudioCtxRef.current.close().catch(() => {});
      inputAudioCtxRef.current = null;
    }
    if (outputAudioCtxRef.current) {
      outputAudioCtxRef.current.close().catch(() => {});
      outputAudioCtxRef.current = null;
    }

    setSession(prev => ({ ...prev, isActive: false }));
    setIsConnecting(false);
  }, []);

  const startSession = useCallback(async (mode: AppMode) => {
    if (session.isActive) stopSession();
    setIsConnecting(true);

    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      // CRITICAL: Create new GoogleGenAI instance right before making API call
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      const inputCtx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
      const outputCtx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      inputAudioCtxRef.current = inputCtx;
      outputAudioCtxRef.current = outputCtx;
      nextStartTimeRef.current = 0;

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: {
            voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Zephyr' } },
          },
          systemInstruction: SYSTEM_INSTRUCTION + `\n\nCURRENT MODE: ${mode}`,
          inputAudioTranscription: {},
          outputAudioTranscription: {}
        },
        callbacks: {
          onopen: () => {
            setIsConnecting(false);
            setSession({ isActive: true, mode, startTime: Date.now() });

            const source = inputCtx.createMediaStreamSource(stream);
            const scriptProcessor = inputCtx.createScriptProcessor(4096, 1, 1);
            scriptProcessor.onaudioprocess = (e) => {
              const inputData = e.inputBuffer.getChannelData(0);
              const pcmBlob = createPcmBlob(inputData);
              // CRITICAL: Ensure sendRealtimeInput is called only after session promise resolves
              sessionPromise.then((s) => {
                s.sendRealtimeInput({ media: pcmBlob });
              });
            };
            source.connect(scriptProcessor);
            scriptProcessor.connect(inputCtx.destination);
          },
          onmessage: async (message: LiveServerMessage) => {
            // Audio Output Handling
            const audioData = message.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
            if (audioData) {
              const audioBuffer = await decodeAudioData(decode(audioData), outputCtx, 24000, 1);
              const source = outputCtx.createBufferSource();
              source.buffer = audioBuffer;
              source.connect(outputCtx.destination);

              nextStartTimeRef.current = Math.max(nextStartTimeRef.current, outputCtx.currentTime);
              source.start(nextStartTimeRef.current);
              nextStartTimeRef.current += audioBuffer.duration;

              activeSourcesRef.current.add(source);
              source.onended = () => activeSourcesRef.current.delete(source);
            }

            // Transcription Handling
            if (message.serverContent?.inputTranscription) {
              currentTranscriptionRef.current.user += message.serverContent.inputTranscription.text;
            }
            if (message.serverContent?.outputTranscription) {
              currentTranscriptionRef.current.model += message.serverContent.outputTranscription.text;
            }

            if (message.serverContent?.turnComplete) {
              const userText = currentTranscriptionRef.current.user;
              const modelText = currentTranscriptionRef.current.model;

              if (userText) {
                setTranscriptions(prev => [...prev, {
                  id: Math.random().toString(),
                  role: 'user',
                  text: userText,
                  timestamp: Date.now()
                }]);
              }
              if (modelText) {
                setTranscriptions(prev => [...prev, {
                  id: Math.random().toString(),
                  role: 'model',
                  text: modelText,
                  timestamp: Date.now()
                }]);
              }

              currentTranscriptionRef.current = { user: '', model: '' };
            }

            if (message.serverContent?.interrupted) {
              activeSourcesRef.current.forEach(s => {
                try { s.stop(); } catch(e) {}
              });
              activeSourcesRef.current.clear();
              nextStartTimeRef.current = 0;
            }
          },
          onerror: (e) => console.error("Session error:", e),
          onclose: () => stopSession()
        }
      });

      sessionPromiseRef.current = sessionPromise;

    } catch (err: any) {
      console.error("Failed to start session:", err);
      setIsConnecting(false);

      // If the request fails with 'Requested entity was not found.', reset key selection state
      if (err?.message?.includes("Requested entity was not found")) {
        setNeedsKey(true);
        window.aistudio?.openSelectKey();
      }
    }
  }, [session.isActive, stopSession]);

  const changeMode = (newMode: AppMode) => {
    if (session.isActive && session.mode === newMode) return;
    setTranscriptions([]);
    startSession(newMode);
  };

  return (
    <div className="flex flex-col min-h-screen bg-slate-50 text-slate-900">
      <Header needsKey={needsKey} onOpenKey={handleOpenKey} />

      <main className="flex-1 flex flex-col md:flex-row max-w-[1600px] mx-auto w-full p-4 md:p-6 gap-6 h-[calc(100vh-64px)] overflow-hidden">

        {/* Navigation Sidebar */}
        <nav className="w-full md:w-64 lg:w-72 flex flex-col space-y-2 overflow-y-auto pr-2">
          <div className="mb-4">
            <h2 className="text-xs font-bold text-slate-400 uppercase tracking-widest px-4 mb-2">Practice Modes</h2>
            <div className="space-y-1">
              {Object.values(AppMode).map((m) => (
                <SidebarItem 
                  key={m} 
                  mode={m} 
                  active={session.mode === m} 
                  onClick={changeMode} 
                />
              ))}
            </div>
          </div>

          <div className="mt-auto bg-blue-50 border border-blue-100 rounded-2xl p-4">
            <h3 className="font-bold text-blue-900 text-sm mb-1">Coach Pro Tip</h3>
            <p className="text-blue-700 text-xs leading-relaxed">
              "Try to use transition words like 'Furthermore' or 'On the other hand' to sound more professional."
            </p>
          </div>
        </nav>

        {/* Chat / Interaction Area */}
        <section className="flex-1 flex flex-col bg-white rounded-3xl border border-slate-200 shadow-sm overflow-hidden">
          <div className="flex-1 overflow-y-auto p-4 md:p-6 space-y-6 scroll-smooth">
            {!session.isActive && !isConnecting && (
              <div className="h-full flex flex-col items-center justify-center text-center max-w-md mx-auto">
                <div className="w-20 h-20 bg-blue-100 rounded-full flex items-center justify-center mb-6">
                  <span className="text-4xl">🎙️</span>
                </div>
                <h2 className="text-2xl font-bold mb-2">Ready to Speak English?</h2>
                <p className="text-slate-500 mb-8">Choose a session mode from the left and start practicing naturally with your AI Coach.</p>
                <button 
                  onClick={() => startSession(session.mode)}
                  className="bg-blue-600 hover:bg-blue-700 text-white px-8 py-3 rounded-2xl font-bold transition-all transform hover:scale-105 shadow-lg"
                >
                  Start Session Now
                </button>
              </div>
            )}

            {isConnecting && (
              <div className="h-full flex flex-col items-center justify-center">
                <div className="relative">
                  <div className="w-16 h-16 border-4 border-blue-200 border-t-blue-600 rounded-full animate-spin"></div>
                  <span className="absolute inset-0 flex items-center justify-center text-xs font-bold text-blue-600">AI</span>
                </div>
                <p className="mt-4 text-slate-500 font-medium">Connecting to your coach...</p>
              </div>
            )}

            {transcriptions.map((t) => (
              <div 
                key={t.id} 
                className={`flex ${t.role === 'user' ? 'justify-end' : 'justify-start'}`}
              >
                <div 
                  className={`max-w-[85%] md:max-w-[70%] p-4 rounded-2xl ${
                    t.role === 'user' 
                      ? 'bg-blue-600 text-white rounded-tr-none' 
                      : 'bg-slate-100 text-slate-800 rounded-tl-none'
                  }`}
                >
                  {t.role === 'model' && (
                    <div className="text-[10px] font-bold uppercase tracking-wider mb-1 opacity-60">Coach</div>
                  )}
                  <p className="text-sm md:text-base leading-relaxed whitespace-pre-wrap">{t.text}</p>
                </div>
              </div>
            ))}
          </div>

          {/* Persistent Control Bar */}
          <div className="p-4 bg-slate-50 border-t flex items-center justify-between">
            <div className="flex items-center space-x-3">
              <div className={`w-3 h-3 rounded-full ${session.isActive ? 'bg-green-500 animate-pulse' : 'bg-slate-300'}`}></div>
              <span className="text-sm font-medium text-slate-600">
                {session.isActive ? `Recording ${MODE_INFO[session.mode].title}...` : 'Microphone Idle'}
              </span>
            </div>

            <div className="flex items-center space-x-4">
               {session.isActive && (
                 <button 
                   onClick={stopSession}
                   className="bg-red-50 text-red-600 hover:bg-red-100 px-4 py-2 rounded-xl font-bold text-sm transition-colors border border-red-100"
                 >
                   End Session
                 </button>
               )}
               <button 
                onClick={() => session.isActive ? stopSession() : startSession(session.mode)}
                className={`w-12 h-12 flex items-center justify-center rounded-full transition-all ${
                  session.isActive 
                    ? 'bg-red-500 hover:bg-red-600 text-white shadow-red-200 shadow-lg scale-110' 
                    : 'bg-blue-600 hover:bg-blue-700 text-white'
                }`}
              >
                {session.isActive ? (
                  <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                  </svg>
                ) : (
                  <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z" />
                  </svg>
                )}
              </button>
            </div>
          </div>
        </section>

        {/* Feedback Panel (Right Side) */}
        <aside className="hidden lg:flex w-80 xl:w-96 flex-col gap-6 overflow-y-auto pr-2">
          <div className="bg-white border border-slate-200 rounded-3xl p-6 shadow-sm">
            <h3 className="text-lg font-bold mb-4 flex items-center gap-2">
              <span className="text-blue-600">📝</span> Live Corrections
            </h3>
            <div className="space-y-4">
              {transcriptions.filter(t => t.role === 'model' && t.text.toLowerCase().includes('mistake:')).length === 0 ? (
                <div className="py-10 text-center">
                  <p className="text-slate-400 text-sm">Corrections will appear here as you speak.</p>
                </div>
              ) : (
                transcriptions.filter(t => t.role === 'model' && t.text.toLowerCase().includes('mistake:')).slice(-3).map((t, idx) => (
                  <div key={idx} className="bg-slate-50 p-4 rounded-xl border border-slate-100">
                    <p className="text-xs text-slate-400 font-mono mb-2">FEEDBACK RECENT</p>
                    <div className="text-sm prose prose-slate max-w-full overflow-hidden text-ellipsis whitespace-pre-wrap">
                      {t.text.split('Mistake:').slice(-1)}
                    </div>
                  </div>
                ))
              )}
            </div>
          </div>

          <div className="bg-gradient-to-br from-slate-800 to-slate-900 rounded-3xl p-6 text-white shadow-xl">
            <h3 className="text-lg font-bold mb-4 flex items-center gap-2">
              <span>📊</span> Session Stats
            </h3>
            <div className="space-y-4">
              <div className="flex justify-between items-center py-2 border-b border-slate-700">
                <span className="text-slate-400 text-sm">Duration</span>
                <span className="font-medium">{session.startTime ? `${Math.floor((Date.now() - session.startTime) / 60000)}m` : '--'}</span>
              </div>
              <div className="flex justify-between items-center py-2 border-b border-slate-700">
                <span className="text-slate-400 text-sm">Vocabulary Points</span>
                <span className="text-blue-400 font-bold">+12</span>
              </div>
              <div className="flex justify-between items-center py-2">
                <span className="text-slate-400 text-sm">Confidence Level</span>
                <div className="flex gap-1">
                  {[1,2,3,4,5].map(i => (
                    <div key={i} className={`w-2 h-4 rounded-sm ${i <= 3 ? 'bg-blue-500' : 'bg-slate-700'}`}></div>
                  ))}
                </div>
              </div>
            </div>
            <button className="w-full mt-6 py-3 bg-white/10 hover:bg-white/20 rounded-xl text-sm font-bold transition-all">
              View Growth Analytics
            </button>
          </div>
        </aside>
      </main>
    </div>
  );
};

export default App;

export enum AppMode {
  DAILY = 'daily',
  MEETING = 'meeting',
  PRESENTATION = 'presentation',
  DEBATE = 'debate',
  PRONUNCIATION = 'pronunciation',
  CONFIDENCE = 'confidence'
}

export interface TranscriptionEntry {
  id: string;
  role: 'user' | 'model';
  text: string;
  timestamp: number;
  suggestion?: string; // New field for rephrasing suggestions
}

export interface SessionState {
  isActive: boolean;
  mode: AppMode;
  startTime: number | null;
}

export interface Correction {
  original: string;
  corrected: string;
  explanation: string;
  alternative: string;
}

/**
 * Interface for AI Studio environment global
 */
export interface AIStudio {
  hasSelectedApiKey: () => Promise<boolean>;
  openSelectKey: () => Promise<void>;
}

declare global {
  interface Window {
    /**
     * The aistudio object provided by the environment
     */
    readonly aistudio: AIStudio;
  }
}

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { GoogleGenAI, Modality, LiveServerMessage } from '@google/genai';
import { AppMode, TranscriptionEntry, SessionState } from './types';
import { SYSTEM_INSTRUCTION, MODE_INFO } from './constants';
import { encode, decode, decodeAudioData, createPcmBlob } from './utils/audio';

// UI Components
const SidebarItem: React.FC<{ 
