  }
}

import React, { useState, useEffect, useRef, useCallback, useMemo } from 'react';
import { GoogleGenAI, Modality, LiveServerMessage } from '@google/genai';
import { AppMode, TranscriptionEntry, SessionState } from './types';
import { SYSTEM_INSTRUCTION, MODE_INFO } from './constants';
import { encode, decode, decodeAudioData, createPcmBlob } from './utils/audio';

// --- TRANSLATION UTILITIES ---

interface WordInfo {
  translation: string;
  ipa: string;
  example: string;
}

const translationCache = new Map<string, WordInfo>();

// Component for individual hoverable words
const HoverableWord: React.FC<{ word: string }> = ({ word }) => {
  const [showTooltip, setShowTooltip] = useState(false);
  const [data, setData] = useState<WordInfo | null>(null);
  const [loading, setLoading] = useState(false);
  const hoverTimeout = useRef<number | null>(null);

  const cleanWord = word.replace(/[^\w]/g, '').toLowerCase();
  const isActuallyAWord = cleanWord.length > 0;

  const fetchTranslation = async () => {
    if (!cleanWord) return;
    if (translationCache.has(cleanWord)) {
      setData(translationCache.get(cleanWord)!);
      return;
    }

    setLoading(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Translate the English word "${cleanWord}" to Vietnamese. Provide the IPA pronunciation and a very short usage example. Return ONLY JSON in this format: {"translation": "...", "ipa": "...", "example": "..."}`,
        config: { responseMimeType: "application/json" }
      });

      const result = JSON.parse(response.text || '{}') as WordInfo;
      translationCache.set(cleanWord, result);
      setData(result);
    } catch (e) {
      console.error("Translation error", e);
    } finally {
      setLoading(false);
    }
  };

  const handleMouseEnter = () => {
    if (!isActuallyAWord) return;
    hoverTimeout.current = window.setTimeout(() => {
      setShowTooltip(true);
      fetchTranslation();
    }, 400);
  };

  const handleMouseLeave = () => {
    if (hoverTimeout.current) clearTimeout(hoverTimeout.current);
    setShowTooltip(false);
  };

  if (!isActuallyAWord) return <span>{word}</span>;

  return (
    <span 
      className="relative inline-block cursor-help hover:bg-blue-100/50 hover:text-blue-700 rounded px-0.5 transition-colors group"
      onMouseEnter={handleMouseEnter}
      onMouseLeave={handleMouseLeave}
    >
      {word}
      {showTooltip && (
        <div className="absolute bottom-full left-1/2 -translate-x-1/2 mb-2 z-50 w-48 animate-in fade-in zoom-in duration-200">
          <div className="bg-white/90 backdrop-blur-md border border-slate-200 shadow-xl rounded-xl p-3 text-slate-800 text-xs">
            {loading ? (
              <div className="flex items-center space-x-2 py-1">
                <div className="w-2 h-2 bg-blue-500 rounded-full animate-bounce"></div>
                <div className="w-2 h-2 bg-blue-500 rounded-full animate-bounce [animation-delay:0.2s]"></div>
                <span className="text-slate-400">Translating...</span>
              </div>
            ) : data ? (
              <div className="space-y-1.5">
                <div className="flex justify-between items-start">
                  <span className="font-bold text-blue-600 text-sm">{data.translation}</span>
                  <span className="text-[10px] text-slate-400 font-mono">{data.ipa}</span>
                </div>
                <div className="h-px bg-slate-100 w-full"></div>
                <p className="italic text-slate-500 leading-tight">"{data.example}"</p>
              </div>
            ) : (
              <span className="text-red-400">Failed to load</span>
            )}
            {/* Tooltip Arrow */}
            <div className="absolute top-full left-1/2 -translate-x-1/2 w-0 h-0 border-l-[6px] border-l-transparent border-r-[6px] border-r-transparent border-t-[6px] border-t-white/90"></div>
          </div>
        </div>
      )}
    </span>
  );
};

// --- MAIN COMPONENTS ---

